from robot.errors import ExecutionFailed

from taf.rfrl.csv4all.resources.test_cases import UpgradeTest
from taf.rfrl.csv4all.resources.utilities.exceptions import FatalError
from taf.rfrl.csv4all.resources.utilities.utilities import check_uuf_tags
from taf.rfrl.csv4all.resources.test_cases.exceptions import RecoveryAttemptFailedError
from taf.rfrl.csv4all.resources.node.exceptions import WrongSwVersion
from taf.rfrl.csv4all.resources.utilities.decorators import method_decorator


class PreliminaryUpgrade(UpgradeTest):

    def run_test(self):
        uuf_tag = check_uuf_tags()
        try:
            if uuf_tag:
                self.run_setup()
                self.execute_test_in_loop()
                if any(nodes_results != "passed" for nodes_results in self.test_results.values()):
                    self.recovery_bts_after_fail()
                    raise ExecutionFailed("Preliminary upgrade failed but further execution will be continued")
            else:
                self.report_uuf_tag_omission()
                raise ExecutionFailed("The UUF tag has not been added, so the preliminary upgrade will be skipped")
        except (RecoveryAttemptFailedError, WrongSwVersion):
            raise FatalError("Recovery of failed nodes fails! Further Execution will be aborted!")
        finally:
            self.run_teardown()

    @method_decorator()
    def report_uuf_tag_omission(self):
        if self.report_to_rp:
            self._common_test_setup()
            self.test_reporter.uuf_case_type = self.uuf_case_type
            self.current_iteration = "Iteration_1"
            for node in self.test_nodes:
                self.test_reporter.set_variables_from_node(node)
                self.test_reporter.fetch_scout_and_set_test_id(node)
                self.test_reporter.report_result_to_uuf_dashboard(
                    node, "failed", self.kpi.get_uuf_kpi(self.test_reporter.uuf_case_type), self.current_iteration)
        if self.notifications:
            self.send_email("failed", f"{self.current_iteration}\nThe UUF tag was skipped!")
